/**
 * Bivane · 风格一：Vant 复刻
 * 取值来源：Vant 4 源码 packages/vant/src/style/css-variables.less
 *          以及各组件 index.less 的 :root 段
 *          （button / cell / cell-group / tag / badge / popup / dialog / toast / overlay）
 * 校准日期：2026-09-21（P0 静态件）、2026-09-21（P1 弹层件）
 *
 * 规则一：组件只允许引用本文件的语义 token，禁止硬编码色值。
 *
 * 规则二（内边距 token 必须拆分量）：
 *   Vant 原始写法是 padding 简写（如 `--van-button-normal-padding: 0 15px`）。
 *   但 Tailwind 的 `[padding:var(--x)]` 任意属性语法不参与 tailwind-merge 的冲突消解，
 *   会被同元素上的 `p-0` / 其它 padding 工具类反向覆盖（实测按钮左右内边距归零）。
 *   因此需要区分方向的内边距一律拆成 `-padding-x` / `-padding-y` 分量，
 *   组件侧只用 `px-[...]` / `py-[...]` 消费——这两个前缀在 tailwind-merge 里有独立分组，
 *   既能正确覆盖自身默认值，也能被外部 className 覆盖。
 *   注：仅单值（上下左右同值）且不与其它 padding 工具类共存的场景才可保留简写。
 */

:root,
:host {
  /* ---------- 色板（Color Palette）---------- */
  --bv-black: #000;
  --bv-white: #fff;
  --bv-gray-1: #f7f8fa;
  --bv-gray-2: #f2f3f5;
  --bv-gray-3: #ebedf0;
  --bv-gray-4: #dcdee0;
  --bv-gray-5: #c8c9cc;
  --bv-gray-6: #969799;
  --bv-gray-7: #646566;
  --bv-gray-8: #323233;
  --bv-red: #ee0a24;
  --bv-blue: #1989fa;
  --bv-orange: #ff976a;
  --bv-orange-dark: #ed6a0c;
  --bv-orange-light: #fffbe8;
  --bv-green: #07c160;

  /* ---------- 渐变（Gradient）---------- */
  --bv-gradient-red: linear-gradient(to right, #ff6034, #ee0a24);
  --bv-gradient-orange: linear-gradient(to right, #ffd01e, #ff8917);

  /* ---------- 语义色（Component Colors）---------- */
  --bv-primary: var(--bv-blue);
  --bv-success: var(--bv-green);
  --bv-danger: var(--bv-red);
  --bv-warning: var(--bv-orange);
  --bv-text: var(--bv-gray-8);
  --bv-text-2: var(--bv-gray-6);
  --bv-text-3: var(--bv-gray-5);
  --bv-active-color: var(--bv-gray-2);
  --bv-active-opacity: 0.6;
  --bv-disabled-opacity: 0.5;
  --bv-background: var(--bv-gray-1);
  --bv-background-2: var(--bv-white);
  --bv-background-3: var(--bv-white);

  /* 语义别名（Bivane 扩展，便于组件书写，不改变 Vant 语义） */
  --bv-border: var(--bv-gray-3);
  --bv-surface: var(--bv-background-2);
  --bv-muted: var(--bv-background);

  /* ---------- 间距（Padding）---------- */
  --bv-padding-base: 4px;
  --bv-padding-xs: 8px;
  --bv-padding-sm: 12px;
  --bv-padding-md: 16px;
  --bv-padding-lg: 24px;
  --bv-padding-xl: 32px;

  /* ---------- 字体（Font）---------- */
  --bv-font-bold: 600;
  --bv-font-xs: 10px;
  --bv-font-sm: 12px;
  --bv-font-md: 14px;
  --bv-font-lg: 16px;
  --bv-line-xs: 14px;
  --bv-line-sm: 18px;
  --bv-line-md: 20px;
  --bv-line-lg: 22px;
  --bv-base-font:
    -apple-system, BlinkMacSystemFont, "Helvetica Neue", Helvetica,
    "Segoe UI", Arial, Roboto, "PingFang SC", "miui", "Hiragino Sans GB",
    "Microsoft Yahei", sans-serif;

  /* ---------- 动画（Animation）---------- */
  --bv-duration-base: 0.3s;
  --bv-duration-fast: 0.2s;
  --bv-ease-out: ease-out;
  --bv-ease-in: ease-in;

  /* ---------- 边框（Border）---------- */
  --bv-border-width: 1px;
  --bv-radius-sm: 2px;
  --bv-radius-md: 4px;
  --bv-radius-lg: 8px;
  --bv-radius-max: 999px;

  /* ---------- 层级（Z-index，Vant 惯例）---------- */
  --bv-z-index-1: 1;
  --bv-z-popup: 2000;
  --bv-z-overlay: 1999;
  --bv-z-toast: 3000;

  /* ---------- 断点（仅文档用，JS 侧读 ResponsiveProvider 配置）---------- */
  --bv-breakpoint: 768px;
}

/* ---------- 组件级 token：Button ---------- */
:root,
:host {
  --bv-button-mini-height: 24px;
  --bv-button-mini-padding-x: var(--bv-padding-base); /* Vant: 0 4px */
  --bv-button-mini-font: var(--bv-font-xs);
  --bv-button-small-height: 32px;
  --bv-button-small-padding-x: var(--bv-padding-xs); /* Vant: 0 8px */
  --bv-button-small-font: var(--bv-font-sm);
  --bv-button-normal-padding-x: 15px; /* Vant: 0 15px */
  --bv-button-normal-font: var(--bv-font-md);
  --bv-button-large-height: 50px;
  --bv-button-default-height: 44px;
  --bv-button-default-line-height: 1.2;
  --bv-button-default-font: var(--bv-font-lg);
  --bv-button-default-color: var(--bv-text);
  --bv-button-default-background: var(--bv-background-2);
  --bv-button-default-border: var(--bv-gray-4);
  --bv-button-border-width: var(--bv-border-width);
  --bv-button-radius: var(--bv-radius-md);
  --bv-button-plain-background: var(--bv-white);
  --bv-button-icon-size: 1.2em;
  --bv-button-loading-icon-size: 20px;
  --bv-button-press-overlay: 0.1; /* 按压态黑色蒙层透明度（Vant 用 ::before） */
}

/* ---------- 组件级 token：Cell / CellGroup ---------- */
:root,
:host {
  --bv-cell-font: var(--bv-font-md);
  --bv-cell-line-height: 24px;
  --bv-cell-vertical-padding: 10px;
  --bv-cell-horizontal-padding: var(--bv-padding-md);
  --bv-cell-text-color: var(--bv-text);
  --bv-cell-background: var(--bv-background-2);
  --bv-cell-border-color: var(--bv-border);
  --bv-cell-active-color: var(--bv-active-color);
  --bv-cell-required-color: var(--bv-danger);
  --bv-cell-label-color: var(--bv-text-2);
  --bv-cell-label-font: var(--bv-font-sm);
  --bv-cell-label-line-height: var(--bv-line-sm);
  --bv-cell-label-margin-top: var(--bv-padding-base);
  --bv-cell-value-color: var(--bv-text-2);
  --bv-cell-icon-size: 16px;
  --bv-cell-right-icon-color: var(--bv-gray-6);
  --bv-cell-large-vertical-padding: var(--bv-padding-sm);
  --bv-cell-large-title-font: var(--bv-font-lg);
  --bv-cell-large-label-font: var(--bv-font-md);

  --bv-cell-group-background: var(--bv-background-2);
  --bv-cell-group-title-color: var(--bv-text-2);
  --bv-cell-group-title-padding: var(--bv-padding-md) var(--bv-padding-md);
  --bv-cell-group-title-font: var(--bv-font-md);
  --bv-cell-group-title-line-height: 16px;
  --bv-cell-group-inset-margin: 0 var(--bv-padding-md);
  --bv-cell-group-inset-radius: var(--bv-radius-lg);
}

/* ---------- 组件级 token：Tag ---------- */
:root,
:host {
  --bv-tag-padding-x: var(--bv-padding-base); /* Vant: 0 4px */
  --bv-tag-padding-y: 0px;
  --bv-tag-text-color: var(--bv-white);
  --bv-tag-font: var(--bv-font-sm);
  --bv-tag-radius: 2px;
  --bv-tag-line-height: 16px;
  --bv-tag-medium-padding-x: 6px; /* Vant: 2px 6px */
  --bv-tag-medium-padding-y: 2px;
  --bv-tag-large-padding-x: var(--bv-padding-xs); /* Vant: 4px 8px */
  --bv-tag-large-padding-y: var(--bv-padding-base);
  --bv-tag-large-radius: var(--bv-radius-md);
  --bv-tag-large-font: var(--bv-font-md);
  --bv-tag-round-radius: var(--bv-radius-max);
  --bv-tag-default-color: var(--bv-gray-6);
  --bv-tag-plain-background: var(--bv-background-2);
}

/* ---------- 组件级 token：Overlay 遮罩 ---------- */
:root,
:host {
  --bv-overlay-background: rgba(0, 0, 0, 0.7); /* Vant: rgba(0,0,0,.7) */
  --bv-overlay-z-index: var(
    --bv-z-overlay
  ); /* Vant 内部为 1（相对值），这里用绝对层级 */
  /* PC 端蒙层更浅：宽屏下 0.7 的蒙层压迫感过强（Bivane 扩展，见 modes.css 的模式覆盖） */
  --bv-overlay-pc-background: rgba(0, 0, 0, 0.45);
}

/* ---------- 组件级 token：Popup 弹层 ---------- */
:root,
:host {
  --bv-popup-background: var(--bv-background-2);
  --bv-popup-round-radius: 16px; /* Vant: --van-popup-round-radius */
  --bv-popup-close-icon-size: 22px;
  --bv-popup-close-icon-color: var(--bv-gray-5);
  --bv-popup-close-icon-margin: var(--bv-padding-md);
  --bv-popup-close-icon-z-index: 1;
  --bv-popup-z-index: var(--bv-z-popup);
  /* 进出场时长，与 --bv-duration-base 同源；H5 用 300ms，PC 收敛到 200ms（见 modes.css） */
  --bv-popup-duration: 300ms;
  /* 底部弹层最大高度：留出顶部安全区，超出内部滚动 */
  --bv-popup-max-height: 90vh;
  /* H5 居中模态的最大宽度：两侧各留一个 padding-md（=16px）。
   逐字对齐 Vant `.van-popup--center { max-width: calc(100vw - var(--van-padding-md) * 2) }`。
   不要用 90vw —— 大屏下留白比例会失控，且与 Vant 的「固定留白」语义不同。 */
  --bv-popup-center-max-width: calc(100vw - var(--bv-padding-md) * 2);
  /* 下拉关闭的判定阈值 */
  --bv-popup-drag-close-distance: 80px; /* 拖拽超过该距离即关闭 */
  --bv-popup-drag-close-velocity: 0.5; /* 或速度超过该值（px/ms）即关闭 */
  /* PC 居中模态（Bivane 扩展：Vant Popup 无 PC 形态） */
  --bv-popup-pc-width: 480px;
  --bv-popup-pc-max-height: 80vh;
  --bv-popup-pc-shadow: 0 12px 32px rgba(0, 0, 0, 0.18);
  --bv-popup-pc-radius: var(--bv-radius-lg);
}

/* ---------- 组件级 token：Dialog 对话框 ---------- */
:root,
:host {
  --bv-dialog-font: var(--bv-font-lg);
  --bv-dialog-radius: 16px;
  --bv-dialog-background: var(--bv-background-2);
  --bv-dialog-header-font-weight: var(--bv-font-bold);
  --bv-dialog-header-line-height: 24px;
  --bv-dialog-header-padding-top: 26px;
  --bv-dialog-header-padding-bottom: 0px;
  --bv-dialog-header-isolated-padding-y: var(
    --bv-padding-lg
  ); /* Vant: 24px 0 */
  --bv-dialog-message-padding-x: var(--bv-padding-lg); /* Vant: 24px 24px */
  --bv-dialog-message-padding-y: var(--bv-padding-lg);
  --bv-dialog-message-font: var(--bv-font-md);
  --bv-dialog-message-line-height: var(--bv-line-md);
  --bv-dialog-message-max-height: 60vh;
  --bv-dialog-has-title-message-color: var(--bv-gray-7);
  --bv-dialog-has-title-message-padding-top: var(--bv-padding-xs);
  --bv-dialog-button-height: 48px;
  --bv-dialog-round-button-height: 36px;
  --bv-dialog-confirm-button-color: var(--bv-primary);
  /* PC 居中模态宽度区间：480 ~ 560px（架构矩阵 §2.1 定义），取中值 520 */
  --bv-dialog-pc-width: 520px;
}

/* ---------- 组件级 token：Toast 轻提示 ---------- */
:root,
:host {
  --bv-toast-max-width: 70%;
  --bv-toast-font: var(--bv-font-md);
  --bv-toast-text-color: var(--bv-white);
  --bv-toast-line-height: var(--bv-line-md);
  --bv-toast-radius: var(--bv-radius-lg);
  --bv-toast-background: rgba(0, 0, 0, 0.7);
  --bv-toast-icon-size: 36px;
  --bv-toast-text-min-width: 96px;
  --bv-toast-text-padding-x: var(--bv-padding-sm); /* Vant: 8px 12px */
  --bv-toast-text-padding-y: var(--bv-padding-xs);
  --bv-toast-default-padding: var(--bv-padding-md);
  --bv-toast-default-width: 88px;
  --bv-toast-default-min-height: 88px;
  --bv-toast-position-top-distance: 20%;
  --bv-toast-position-bottom-distance: 20%;
  --bv-toast-z-index: var(--bv-z-toast);
  /* PC 右上角通知卡片（Bivane 扩展：Vant Toast 无 PC 形态） */
  --bv-toast-pc-width: 340px;
  --bv-toast-pc-gutter: var(--bv-padding-lg);
  --bv-toast-pc-gap: var(--bv-padding-xs);
  --bv-toast-pc-shadow: 0 8px 24px rgba(0, 0, 0, 0.16);
  --bv-toast-pc-close-size: 16px;
}

/* ---------- 组件级 token：Badge ---------- */
:root,
:host {
  --bv-badge-size: 16px;
  --bv-badge-color: var(--bv-white);
  --bv-badge-padding-x: 3px; /* Vant: 0 3px */
  --bv-badge-padding-y: 0px;
  --bv-badge-font: var(--bv-font-sm);
  --bv-badge-font-weight: var(--bv-font-bold);
  --bv-badge-border-width: var(--bv-border-width);
  --bv-badge-background: var(--bv-danger);
  --bv-badge-dot-size: 8px;
}

/* ---------- 公共 token：面板工具栏（H5 弹层头部） ----------
 * 「取消 · 标题 · 确定」这一条是 H5 选择类面板的通用头部：Select / DropdownMenu 在用，
 * 后续的 DatePicker / TimePicker / Picker 也会复用同一组（Vant 的 Picker 工具栏
 * 即此形态：高度 44px、左右文字按钮、居中标题）。
 * 多层下钻时头部多一行「层级行」（--bv-panel-header-breadcrumb-height），
 * 面包屑独占该行、左对齐，工具栏行不受影响（见 panel-header.tsx）。
 *
 * PC 不渲染工具栏（鼠标点选即生效，见 panel-header.tsx 头注），
 * 因此这组没有 *-pc 变体，也不需要进 modes.css。
 *
 * 不新增颜色语义：取消/标题/确定分别复用 --bv-text-2 / --bv-text / --bv-primary，
 * 禁用态复用全局 --bv-disabled-opacity。
 */
:root,
:host {
  --bv-panel-header-height: 44px;
  --bv-panel-header-breadcrumb-height: 32px; /* 层级行高度：只装一行面包屑，比工具栏行矮 */
  --bv-panel-header-padding-x: var(--bv-padding-md);
  --bv-panel-header-line-height: var(--bv-line-md);
  --bv-panel-header-title-inset: 56px; /* 标题两侧各给「取消/确定」文字按钮留的让位宽度 */
  --bv-panel-header-color: var(--bv-text);
  --bv-panel-header-cancel-color: var(--bv-text-2);
  --bv-panel-header-confirm-color: var(--bv-primary);
  --bv-panel-header-disabled-opacity: var(--bv-disabled-opacity);
  --bv-panel-header-icon-size: 16px; /* 返回箭头等图标按钮的尺寸 */
  --bv-panel-header-icon-color: var(--bv-gray-6);
}

/* ---------- 组件级 token：Select 选择器 ----------
 * Vant 没有 Select 组件（它用 Picker / DropdownMenu / Cascader 覆盖不同场景），
 * 因此这一组是 Bivane 扩展，取值基准是 Vant 的 Field + Cell：
 * 触发器沿用 Cell 的纵向节奏（10px + 24px 行高 = 44px 触控热区），
 * H5 选项行沿用矩阵 §2.2 规定的 48px 项高。
 *
 * 注意：本组**不新增任何颜色 token**，颜色一律复用既有语义 token。
 * 原因见架构 §3.4③ —— 新增颜色 token 必须在 vant.css / theme.css / lib/utils.ts
 * 三处同时补齐，漏掉第 2 处会静默导致工具类不生成。颜色复用可以把风险面收敛为零。
 *
 * H5 与 PC 是两份独立实现（模式 C），因此两套密度 token 各写各的、
 * 无需进 modes.css 做模式覆盖：h5/select.tsx 只读不带后缀的，pc/select.tsx 只读 *-pc 的。
 */
:root,
:host {
  /* 触发器（两模式共用一套语义 token；外壳形态差异在组件里由 JS 分支给出） */
  --bv-select-font: var(--bv-font-md);
  --bv-select-line-height: var(--bv-line-md);
  --bv-select-padding-x: var(--bv-padding-md);
  --bv-select-padding-y: 10px; /* 与 Cell 纵向内边距一致：10 + 24 + 10 = 44px */
  --bv-select-text-color: var(--bv-text);
  --bv-select-placeholder-color: var(--bv-text-3);
  --bv-select-icon-size: 16px;
  --bv-select-icon-color: var(--bv-gray-6);
  --bv-select-gap: var(--bv-padding-base);
  --bv-select-disabled-opacity: var(--bv-disabled-opacity);
  /* PC 触发器的固定高度（桌面密度；H5 靠 padding 撑出 44px 热区） */
  --bv-select-pc-trigger-height: 32px;
  --bv-select-pc-trigger-border-color: var(--bv-gray-4);
  --bv-select-pc-trigger-radius: var(--bv-radius-md);

  /* 选项行：H5 项高 48px（矩阵 §2.2 规定，同时是触控热区下限） */
  --bv-select-option-height: 48px;
  --bv-select-option-padding-x: var(--bv-padding-md);
  --bv-select-option-line-height: var(--bv-line-md);
  --bv-select-option-check-size: 16px;
  --bv-select-option-check-color: var(--bv-primary);
  --bv-select-option-active-background: var(--bv-active-color);
  --bv-select-option-hover-background: var(--bv-muted);
  --bv-select-option-disabled-color: var(--bv-text-3);

  /* 面板（H5：由 Popup 承载底部弹层形态，这里只定内部密度） */
  --bv-select-panel-max-height: 60vh;
  --bv-select-search-height: 44px;
  --bv-select-empty-font: var(--bv-font-md);
  --bv-select-empty-line-height: var(--bv-line-md);
  --bv-select-empty-padding-y: var(--bv-padding-xl);
  --bv-select-group-title-font: var(--bv-font-sm);
  --bv-select-group-title-line-height: var(--bv-line-sm);
  --bv-select-group-title-padding-x: var(--bv-padding-md);
  --bv-select-group-title-padding-y: var(--bv-padding-xs);
  --bv-select-group-title-color: var(--bv-text-2);
  --bv-select-group-title-background: var(--bv-background-3);

  /* PC 锚定下拉浮层（矩阵 §2.2：桌面用桌面密度，与 H5 的 48px 项高刻意不同） */
  --bv-select-pc-option-height: 36px;
  --bv-select-pc-panel-min-width: 160px;
  --bv-select-pc-panel-max-height: 280px;
  --bv-select-pc-offset: var(--bv-padding-base);
  --bv-select-pc-radius: var(--bv-radius-md);
  --bv-select-pc-shadow: 0 6px 20px rgba(0, 0, 0, 0.12);
  --bv-select-pc-duration: 120ms;
  --bv-select-pc-z-index: var(--bv-z-popup);
  --bv-select-pc-padding-y: var(--bv-padding-base);
}

/* ---------- 组件级 token：DropdownMenu 下拉菜单 ----------
 * 与 Vant 的 DropdownMenu 不是同一件东西：Vant 那个是「菜单栏 + 多项下拉」
 * （v-model 管的是当前激活的菜单项），而矩阵 §2.2 定义的是**触发器 + 菜单树**
 * 的通用下拉菜单（二级菜单、快捷键提示、分隔线）。因此本组是 Bivane 扩展，
 * 触发器的纵向节奏与 Select 对齐（沿用 Cell 的 10 + 24 + 10 = 44px 热区）。
 *
 * 不新增任何颜色 token（架构 §3.4③ 的三处补齐规则），危险项/悬停/按压
 * 一律复用既有语义 token：--bv-danger / --bv-muted / --bv-active-color。
 *
 * H5 与 PC 是两份独立实现（模式 C），两套密度各写各的，
 * 不需要进 modes.css 做模式覆盖（架构 §6.5 ②）。
 */
:root,
:host {
  /* 触发器（两模式共用；外壳形态差异在 menu-parts 里由 JS 分支给出） */
  --bv-menu-font: var(--bv-font-md);
  --bv-menu-line-height: var(--bv-line-md);
  --bv-menu-padding-x: var(--bv-padding-md);
  --bv-menu-padding-y: 10px;
  --bv-menu-text-color: var(--bv-text);
  --bv-menu-icon-size: 16px;
  --bv-menu-icon-color: var(--bv-gray-6);
  --bv-menu-gap: var(--bv-padding-base);
  --bv-menu-disabled-opacity: var(--bv-disabled-opacity);
  --bv-menu-pc-trigger-height: 32px;
  --bv-menu-pc-trigger-border-color: var(--bv-gray-4);
  --bv-menu-pc-trigger-radius: var(--bv-radius-md);

  /* 行（H5：48px，触控热区下限，与 Select 的项高同一节奏） */
  --bv-menu-row-height: 48px;
  --bv-menu-row-padding-x: var(--bv-padding-md);
  --bv-menu-row-line-height: var(--bv-line-md);
  --bv-menu-row-active-background: var(--bv-active-color);
  --bv-menu-row-hover-background: var(--bv-muted);
  --bv-menu-row-disabled-color: var(--bv-text-3);
  --bv-menu-row-danger-color: var(--bv-danger);
  --bv-menu-row-icon-size: 16px;
  --bv-menu-shortcut-font: var(--bv-font-sm);
  --bv-menu-shortcut-line-height: var(--bv-line-sm);
  --bv-menu-shortcut-color: var(--bv-text-3);

  /* 面板（H5 侧由 Popup 承载容器，这里只定内部密度）
   注：标题栏与返回箭头的尺寸不在这里 —— 它们是 h5/menu.tsx 复用的
   公共面板工具栏，token 收在 `--bv-panel-header-*` 那一组（Select 同样在用）。 */
  --bv-menu-panel-max-height: 60vh;
  /* 二级面板推入的时长：与 Popup 的 --bv-popup-duration 保持同一量级，
   否则「抽屉滑上来」与「面板横向推入」会看出两段不同的节奏 */
  --bv-menu-push-duration: 300ms;
  --bv-menu-empty-font: var(--bv-font-md);
  --bv-menu-empty-line-height: var(--bv-line-md);
  --bv-menu-empty-padding-y: var(--bv-padding-xl);
  --bv-menu-divider-color: var(--bv-border);
  --bv-menu-divider-margin-y: var(--bv-padding-xs);

  /* PC 锚定浮层（桌面密度；与 H5 的 48px 行高刻意不同，属两种交互的定义差异） */
  --bv-menu-pc-row-height: 36px;
  --bv-menu-pc-panel-min-width: 160px;
  --bv-menu-pc-panel-max-height: 280px;
  --bv-menu-pc-offset: var(--bv-padding-base);
  --bv-menu-pc-sub-offset: 2px;
  --bv-menu-pc-radius: var(--bv-radius-md);
  --bv-menu-pc-shadow: 0 6px 20px rgba(0, 0, 0, 0.12);
  --bv-menu-pc-duration: 120ms;
  --bv-menu-pc-z-index: var(--bv-z-popup);
  --bv-menu-pc-padding-y: var(--bv-padding-base);
}

/* ---------- 组件级 token：DatePicker 日期选择 ----------
 * 触发器的纵向节奏与 Select / DropdownMenu 对齐（沿用 Cell 的 10 + 24 + 10 = 44px 热区）。
 * PC 是月历而非滚轮，两套密度各写各的；H5 与 PC 是两份独立实现（模式 C），
 * 因此不需要进 modes.css 做模式覆盖（架构 §6.5 ②）。
 *
 * 不新增任何颜色 token（架构 §3.4③ 的三处补齐规则）：
 * 文字/端点/区间/悬停一律复用既有语义 token
 * （--bv-text / --bv-text-2 / --bv-text-3 / --bv-primary / --bv-muted / --bv-active-color），
 * 全部以 `[var(--bv-*)]` 任意值消费，绕开「漏了 theme.css 就静默不生成」那一面。
 *
 * `--bv-date-picker-wheel-item-height` 必须与 hooks/use-picker-column.ts 的
 * WHEEL_ITEM_HEIGHT 保持一致：组件实测行高并优先用实测值，常量只在无布局环境（jsdom）兜底。
 */
:root,
:host {
  /* 触发器（两模式共用；外壳形态差异在 date-parts 里由 JS 分支给出） */
  --bv-date-picker-font: var(--bv-font-md);
  --bv-date-picker-line-height: var(--bv-line-md);
  --bv-date-picker-padding-x: var(--bv-padding-md);
  --bv-date-picker-padding-y: 10px;
  --bv-date-picker-text-color: var(--bv-text);
  --bv-date-picker-text-2-color: var(--bv-text-2);
  --bv-date-picker-text-3-color: var(--bv-text-3);
  --bv-date-picker-placeholder-color: var(--bv-text-3);
  --bv-date-picker-icon-size: 16px;
  --bv-date-picker-icon-color: var(--bv-gray-6);
  --bv-date-picker-gap: var(--bv-padding-base);
  --bv-date-picker-disabled-opacity: var(--bv-disabled-opacity);

  --bv-date-picker-pc-trigger-height: 32px;
  --bv-date-picker-pc-trigger-border-color: var(--bv-gray-4);
  --bv-date-picker-pc-trigger-radius: var(--bv-radius-md);

  /* H5 滚轮：5 行制，行高与 Cell 同为 44px（触控热区下限） */
  --bv-date-picker-wheel-item-height: 44px;
  --bv-date-picker-wheel-item-line-height: var(--bv-line-md);
  --bv-date-picker-wheel-color: var(--bv-text-3);
  --bv-date-picker-wheel-selected-color: var(--bv-text);
  --bv-date-picker-wheel-line-color: var(--bv-border);
  /* 上下渐隐遮罩的起点色 = 弹层底色，否则遮罩会在面板上显出一条色带 */
  --bv-date-picker-wheel-mask-color: var(--bv-popup-background);

  /* H5 区间端点切换条（三列滚轮一次只表达一个日期，端点要显式标出来） */
  --bv-date-picker-range-tabs-gap: var(--bv-padding-base);
  --bv-date-picker-range-tabs-padding-y: var(--bv-padding-xs);
  --bv-date-picker-range-tab-radius: var(--bv-radius-sm);
  --bv-date-picker-range-tab-padding-x: var(--bv-padding-sm);
  --bv-date-picker-range-tab-padding-y: var(--bv-padding-xs);
  --bv-date-picker-range-tab-line-height: var(--bv-line-md);
  --bv-date-picker-range-tab-hint-line-height: var(--bv-line-xs);
  --bv-date-picker-range-tab-active-background: var(--bv-active-color);
  --bv-date-picker-range-tab-active-color: var(--bv-primary);

  /* PC 月历（桌面密度：格高 32px，比 H5 的 44px 行高更紧） */
  --bv-date-picker-pc-panel-width: 252px;
  --bv-date-picker-pc-padding-x: var(--bv-padding-sm);
  --bv-date-picker-pc-padding-y: var(--bv-padding-sm);
  --bv-date-picker-pc-nav-height: 32px;
  --bv-date-picker-pc-nav-color: var(--bv-gray-6);
  --bv-date-picker-pc-weekday-height: 24px;
  --bv-date-picker-pc-weekday-line-height: var(--bv-line-xs);
  --bv-date-picker-pc-weekday-color: var(--bv-text-3);
  --bv-date-picker-pc-cell-height: 32px;
  --bv-date-picker-pc-cell-line-height: var(--bv-line-xs);
  --bv-date-picker-pc-cell-radius: var(--bv-radius-sm);
  --bv-date-picker-pc-cell-selected-background: var(--bv-primary);
  --bv-date-picker-pc-cell-selected-color: var(--bv-white);
  /* 区间内是「带」不是「点」：背景用按压色，端点的实心色才跳得出来 */
  --bv-date-picker-pc-cell-in-range-background: var(--bv-active-color);
  --bv-date-picker-pc-cell-hover-background: var(--bv-muted);
  --bv-date-picker-pc-cell-disabled-opacity: var(--bv-disabled-opacity);
  /* 双月之间不额外留缝：两个面板各自的横向内边距已经构成分隔 */
  --bv-date-picker-pc-dual-gap: 0px;
  --bv-date-picker-pc-radius: var(--bv-radius-md);
  --bv-date-picker-pc-shadow: 0 6px 20px rgba(0, 0, 0, 0.12);
  --bv-date-picker-pc-duration: 160ms;
  --bv-date-picker-pc-z-index: var(--bv-z-popup);

  /* ---------------------------------------------------------------- *
  * TimePicker（与 DatePicker 同族）：两端同一套「拖动滚轮 + 吸附」，只换外壳
  * 颜色 token 一律复用既有语义 token（见 DatePicker 组注释），不新增颜色 token。
  * 滚轮行高必须与 hooks/use-picker-column.ts 的 WHEEL_ITEM_HEIGHT 一致。
  * ---------------------------------------------------------------- */
  /* 触发器（两模式共用；外壳形态差异在 time-parts 里由 JS 分支给出） */
  --bv-time-picker-font: var(--bv-font-md);
  --bv-time-picker-line-height: var(--bv-line-md);
  --bv-time-picker-padding-x: var(--bv-padding-md);
  --bv-time-picker-padding-y: 10px;
  --bv-time-picker-text-color: var(--bv-text);
  --bv-time-picker-text-2-color: var(--bv-text-2);
  --bv-time-picker-text-3-color: var(--bv-text-3);
  --bv-time-picker-placeholder-color: var(--bv-text-3);
  --bv-time-picker-icon-size: 16px;
  --bv-time-picker-icon-color: var(--bv-gray-6);
  --bv-time-picker-gap: var(--bv-padding-base);
  --bv-time-picker-disabled-opacity: var(--bv-disabled-opacity);

  --bv-time-picker-pc-trigger-height: 32px;
  --bv-time-picker-pc-trigger-border-color: var(--bv-gray-4);
  --bv-time-picker-pc-trigger-radius: var(--bv-radius-md);

  /* 滚轮（两端同一套：5 行制，行高与 Cell 同为 44px。触控热区下限，鼠标下不过分稀疏） */
  --bv-time-picker-wheel-item-height: 44px;
  --bv-time-picker-wheel-item-line-height: var(--bv-line-md);
  --bv-time-picker-wheel-color: var(--bv-text-3);
  --bv-time-picker-wheel-selected-color: var(--bv-text);
  --bv-time-picker-wheel-line-color: var(--bv-border);
  /* 上下渐隐遮罩的起点色 = 弹层底色，否则遮罩会在面板上显出一条色带 */
  --bv-time-picker-wheel-mask-color: var(--bv-popup-background);

  /* 区间端点切换条（三列滚轮一次只表达一个时间，端点要显式标出来） */
  --bv-time-picker-range-tabs-gap: var(--bv-padding-base);
  --bv-time-picker-range-tabs-padding-y: var(--bv-padding-xs);
  --bv-time-picker-range-tab-radius: var(--bv-radius-sm);
  --bv-time-picker-range-tab-padding-x: var(--bv-padding-sm);
  --bv-time-picker-range-tab-padding-y: var(--bv-padding-xs);
  --bv-time-picker-range-tab-line-height: var(--bv-line-md);
  --bv-time-picker-range-tab-hint-line-height: var(--bv-line-xs);
  --bv-time-picker-range-tab-active-background: var(--bv-active-color);
  --bv-time-picker-range-tab-active-color: var(--bv-primary);

  /* PC 浮层外壳（定宽盒 + 底部「取消 / 确定」条；滚轮本体复用上面那组 token） */
  --bv-time-picker-pc-panel-width: 200px;
  --bv-time-picker-pc-padding-x: var(--bv-padding-sm);
  --bv-time-picker-pc-padding-y: var(--bv-padding-sm);
  --bv-time-picker-pc-radius: var(--bv-radius-md);
  --bv-time-picker-pc-shadow: 0 6px 20px rgba(0, 0, 0, 0.12);
  --bv-time-picker-pc-duration: 160ms;
  --bv-time-picker-pc-z-index: var(--bv-z-popup);

  /* ---------------------------------------------------------------- *
  * DateTimePicker（DatePicker/TimePicker 同族）：年月日时分秒同一条滚轮列序，
  * 两端同范式只换外壳（模式 B）。视觉取值与 TimePicker 对齐：同触发器密度、
  * 同 5 行制 44px 滚轮；PC 浮层宽度随列数（4/5/6）走，每列固定宽。
  * 颜色一律复用既有语义 token，不新增颜色。
  * ---------------------------------------------------------------- */
  /* 触发器（两模式共用；外壳形态差异在 datetime-parts 里由 JS 分支给出） */
  --bv-datetime-picker-padding-x: var(--bv-padding-md);
  --bv-datetime-picker-padding-y: 10px;
  --bv-datetime-picker-text-color: var(--bv-text);
  --bv-datetime-picker-placeholder-color: var(--bv-text-3);
  --bv-datetime-picker-icon-size: 16px;
  --bv-datetime-picker-icon-color: var(--bv-gray-6);
  --bv-datetime-picker-gap: var(--bv-padding-base);
  --bv-datetime-picker-disabled-opacity: var(--bv-disabled-opacity);

  --bv-datetime-picker-pc-trigger-height: 32px;
  --bv-datetime-picker-pc-trigger-border-color: var(--bv-gray-4);
  --bv-datetime-picker-pc-trigger-radius: var(--bv-radius-md);

  /* 滚轮（两端同一套：5 行制，行高与 TimePicker 同为 44px） */
  --bv-datetime-picker-wheel-item-height: 44px;
  --bv-datetime-picker-wheel-item-line-height: var(--bv-line-md);
  --bv-datetime-picker-wheel-color: var(--bv-text-3);
  --bv-datetime-picker-wheel-selected-color: var(--bv-text);
  --bv-datetime-picker-wheel-line-color: var(--bv-border);
  --bv-datetime-picker-wheel-mask-color: var(--bv-popup-background);

  /* PC 浮层外壳：左月历固定宽 + 右侧时间列（列宽 × 时间列数，组件按列数算） */
  --bv-datetime-picker-column-width: 56px;
  --bv-datetime-picker-pc-padding-x: var(--bv-padding-sm);
  --bv-datetime-picker-pc-padding-y: var(--bv-padding-sm);
  --bv-datetime-picker-pc-radius: var(--bv-radius-md);
  --bv-datetime-picker-pc-shadow: 0 6px 20px rgba(0, 0, 0, 0.12);
  --bv-datetime-picker-pc-duration: 160ms;
  --bv-datetime-picker-pc-z-index: var(--bv-z-popup);
}

/* ---------- 组件级 token：Tooltip 文字提示 ----------
 * Vant 没有 Tooltip 组件，本组是 Bivane 扩展（矩阵 §2.1）。
 * 两端信息相同（一段补充说明）、容器密度不同：
 *   PC = hover/focus 触发的深色跟随气泡（pointer-events:none、不可交互）；
 *   H5 = 常驻的 ⓘ 信息提示条（触屏没有 hover，辅助说明应直接展示，长文折叠走 Ellipsis）。
 * 颜色不注册 bg-bv-* 语义工具类，组件侧一律以任意值 var() 消费（同 DatePicker 组做法）。
 */
:root,
:host {
  /* —— PC 跟随气泡（H5 已不使用浮层） —— */
  --bv-tooltip-background: rgba(0, 0, 0, 0.75);
  --bv-tooltip-color: var(--bv-white);
  --bv-tooltip-font: var(--bv-font-sm);
  --bv-tooltip-line-height: var(--bv-line-sm);
  --bv-tooltip-padding-x: var(--bv-padding-sm);
  --bv-tooltip-padding-y: 6px;
  --bv-tooltip-radius: var(--bv-radius-md);
  --bv-tooltip-max-width: 240px;
  /* 气泡与光标的间距，同时用于键盘聚焦时与触发元素的间距 */
  --bv-tooltip-gap: 12px;
  /* 距视口边缘的最小留白，避免气泡贴边 */
  --bv-tooltip-viewport-margin: var(--bv-padding-xs);
  --bv-tooltip-duration: 120ms;
  --bv-tooltip-z-index: var(--bv-z-popup);
  /* PC：hover 多久后弹出（矩阵：200ms 延迟，防扫过误触） */
  --bv-tooltip-pc-open-delay: 200ms;

  /* —— H5 常驻信息提示条（ⓘ + 说明全文，铺在被说明主体下方） —— */
  --bv-tooltip-h5-info-background: var(--bv-background);
  --bv-tooltip-h5-info-color: var(--bv-text-2);
  --bv-tooltip-h5-info-icon-color: var(--bv-primary);
  --bv-tooltip-h5-info-padding-x: var(--bv-padding-sm);
  --bv-tooltip-h5-info-padding-y: var(--bv-padding-xs);
  --bv-tooltip-h5-info-radius: var(--bv-radius-md);
  /* 行首 ⓘ 与文案的间距 */
  --bv-tooltip-h5-info-gap: var(--bv-padding-base);
  --bv-tooltip-h5-info-icon-size: 14px;
  --bv-tooltip-h5-info-font: var(--bv-font-sm);
  --bv-tooltip-h5-info-line-height: var(--bv-line-sm);
  /* 与上方被说明主体的间距 */
  --bv-tooltip-h5-info-margin-top: var(--bv-padding-xs);
}

/* ---------- 组件级 token：Ellipsis 多行截断 / 展开收起 ----------
 * 两端同形（模式 A），只多一个「展开 / 收起」文字按钮；颜色复用 primary，
 * 字号/行高继承父级（它是通用文本容器，不该自带字号）。
 */
:root,
:host {
  --bv-ellipsis-action-color: var(--bv-primary);
  --bv-ellipsis-action-gap: var(--bv-padding-base);
}

/* ---------- 组件级 token：Popover 气泡弹层 ----------
 * Vant 4 的 Popover 是锚定触发器的轻量气泡（actions 列表）；本组沿用其视觉，
 * 另加 H5 的「内容 > 3 行降级底部抽屉」与 PC 的 Radix Popper 防溢出（矩阵 §2.1）。
 * H5 与 PC 双实现（模式 C），两套行高各写各的，不进 modes.css。
 * 颜色全部复用既有语义 token（text / danger / active / muted / border / surface）。
 */
:root,
:host {
  /* 行：H5 48px 触控热区；PC 36px 桌面密度（与 Select/Menu 同一节奏） */
  --bv-popover-h5-row-height: 48px;
  --bv-popover-pc-row-height: 36px;
  --bv-popover-row-padding-x: var(--bv-padding-md);
  --bv-popover-row-icon-size: 16px;
  --bv-popover-row-gap: var(--bv-padding-base);
  /* 自定义内容区（actions 之外）的内边距；actions 列表本身满宽 flush */
  --bv-popover-content-padding-x: var(--bv-padding-xs);
  --bv-popover-content-padding-y: var(--bv-padding-xs);
  /* H5 轻量气泡限宽；同时是「超行降级」测量探针的宽度（宽度不确定高度就无法判定） */
  --bv-popover-h5-bubble-max-width: 240px;
  /* H5 气泡/抽屉自动分界：动作行 ≤ 该值走气泡，超出走抽屉；实例可用 maxRows prop 覆盖 */
  --bv-popover-h5-bubble-max-rows: 3;
  --bv-popover-pc-panel-min-width: 160px;
  --bv-popover-pc-panel-max-width: 320px;
  --bv-popover-panel-max-height: 60vh;
  --bv-popover-offset: var(--bv-padding-base);
  --bv-popover-radius: var(--bv-radius-lg);
  --bv-popover-shadow: 0 6px 20px rgba(0, 0, 0, 0.12);
  --bv-popover-duration: 120ms;
  --bv-popover-z-index: var(--bv-z-popup);
}

/* ---------- 组件级 token：Picker 通用多列选择 ----------
 * 模式 C：H5 多列滚轮（底部弹层）vs PC 多列纵向面板（锚定浮层）。
 * Cascader 的触发器与 H5 联动滚轮同源复用本组 token，不另立一套滚轮视觉。
 * 颜色全部复用既有语义 token，以任意值 var() 消费，不注册 bg-bv-* 新颜色。
 * `--bv-picker-wheel-item-height` 必须与 hooks/use-picker-column.ts 的
 * WHEEL_ITEM_HEIGHT 保持一致（同 DatePicker/TimePicker 组约定）。
 */
:root,
:host {
  /* 触发器（两模式共用；外壳形态差异在 picker-parts 里由 JS 分支给出） */
  --bv-picker-font: var(--bv-font-md);
  --bv-picker-line-height: var(--bv-line-md);
  --bv-picker-padding-x: var(--bv-padding-md);
  --bv-picker-padding-y: 10px;
  --bv-picker-text-color: var(--bv-text);
  --bv-picker-placeholder-color: var(--bv-text-3);
  --bv-picker-icon-size: 16px;
  --bv-picker-icon-color: var(--bv-gray-6);
  --bv-picker-gap: var(--bv-padding-base);
  --bv-picker-disabled-opacity: var(--bv-disabled-opacity);

  --bv-picker-pc-trigger-height: 32px;
  --bv-picker-pc-trigger-border-color: var(--bv-gray-4);
  --bv-picker-pc-trigger-radius: var(--bv-radius-md);

  /* H5 滚轮：5 行制，行高 44px（触控热区下限；Cascader H5 联动滚轮同组复用） */
  --bv-picker-wheel-item-height: 44px;
  --bv-picker-wheel-item-line-height: var(--bv-line-md);
  --bv-picker-wheel-color: var(--bv-text-3);
  --bv-picker-wheel-selected-color: var(--bv-text);
  --bv-picker-wheel-line-color: var(--bv-border);
  --bv-picker-wheel-mask-color: var(--bv-popup-background);
  /* PC 多列面板里列与列之间的 1px 竖向分隔 */
  --bv-picker-column-divider-color: var(--bv-border);

  /* PC 多列面板：行高 36 与 Cascader 桌面面板一致；列宽 token 是**最小列宽**——
    Picker PC 的列按本列最长项 w-max 撑开（选项不省略），仅在更窄时兜底到 132。
    注意 Cascader 列是固定 132（路径文案可长，固定宽 + 面包屑/搜索承担完整路径），
    不要顺手把 Cascader 也改成 w-max。 */
  --bv-picker-pc-column-width: 132px;
  --bv-picker-pc-row-height: 36px;
  --bv-picker-pc-panel-max-height: 280px;
  --bv-picker-pc-padding-x: var(--bv-padding-sm);
  --bv-picker-pc-padding-y: var(--bv-padding-sm);
  --bv-picker-pc-offset: var(--bv-padding-base);
  --bv-picker-pc-radius: var(--bv-radius-md);
  --bv-picker-pc-shadow: 0 6px 20px rgba(0, 0, 0, 0.12);
  --bv-picker-pc-duration: 160ms;
  --bv-picker-pc-z-index: var(--bv-z-popup);

  /* ---------------------------------------------------------------- *
   * Cascader（PC 专属外壳）：多列级联面板 + 面包屑路径 + 搜索定位。
   * H5 复用 Picker 的触发器与联动滚轮，不在这里重复定义；
   * PC 行宽要放得下「浙江 / 杭州市」这类路径文案，列宽比 Picker 宽。
   * ---------------------------------------------------------------- */
  --bv-cascader-pc-column-width: 132px;
  --bv-cascader-pc-row-height: 36px;
  --bv-cascader-pc-panel-max-height: 280px;
  --bv-cascader-pc-padding-x: var(--bv-padding-sm);
  --bv-cascader-pc-padding-y: var(--bv-padding-sm);
  --bv-cascader-pc-breadcrumb-height: 36px;
  --bv-cascader-pc-offset: var(--bv-padding-base);
  --bv-cascader-pc-radius: var(--bv-radius-md);
  --bv-cascader-pc-shadow: 0 6px 20px rgba(0, 0, 0, 0.12);
  --bv-cascader-pc-duration: 160ms;
  --bv-cascader-pc-z-index: var(--bv-z-popup);
}

/**
 * Bivane · Vant 复刻风格 · 深色主题
 * 取值来源：Vant 4 源码 packages/vant/src/style/css-variables.less（.van-theme-dark）
 * 用法：在根元素或任意容器上加 class="bv-theme-dark"
 */

.bv-theme-dark {
  --bv-text: #f5f5f5;
  --bv-text-2: #707070;
  --bv-text-3: #4d4d4d;
  --bv-border: #3a3a3c;
  --bv-active-color: #3a3a3c;
  --bv-background: #000;
  --bv-background-2: #1c1c1e;
  --bv-background-3: #37363b;

  /* 语义别名跟随重算 */
  --bv-surface: var(--bv-background-2);
  --bv-muted: var(--bv-background);

  /* Vant 深色下 plain 按钮背景改为透明 */
  --bv-button-plain-background: transparent;
}

/**
 * Bivane · 模式相关 token（H5 / PC）
 *
 * 这里放的是**唯一允许随模式变化的 token**，分两类，边界必须守住：
 *
 *  A. 页面骨架节奏（--bv-gutter / --bv-block-padding / --bv-section-gap）
 *     只用于页面与文档层。H5 沿用 Vant 原生紧凑节奏，PC 放宽，
 *     解决「手机栅格被拉到 1200px 后发挤」的问题。
 *
 *  B. 容器形态（遮罩浓度、弹层圆角/宽度/阴影/动画时长）
 *     弹层在两端本就是不同物理形态（底部抽屉 vs 居中模态），
 *     形态参数随模式变化是定义使然，不属于「内部间距随模式漂移」。
 *
 * 禁止：把组件内部间距（--bv-padding-*、--bv-<组件>-padding-*）写进本文件。
 *      组件内部间距在任何模式下都严格等于 Vant 原值，这是视觉保真的底线。
 *      （见 bivane-architecture.md §3.2 间距分层）
 *
 * 横向 gutter 不随模式变化（恒为 16px），否则页面标题会与 Vant 定宽 16px 的
 * 组件内边距错位。
 */

/* ---------- A. 页面骨架默认值（H5 节奏 = Vant 原生） ---------- */
:root {
  --bv-gutter: var(--bv-padding-xs); /* 相邻组件行内间距：H5 8px */
  --bv-block-padding: var(--bv-padding-md); /* 区块纵向内边距：H5 16px */
  --bv-section-gap: var(--bv-padding-lg); /* 区块之间间距：H5 24px */
}

/* ---------- PC：骨架放宽 ---------- */
[data-mode='pc'] {
  --bv-gutter: var(--bv-padding-sm); /* PC 行内间距 12px */
  --bv-block-padding: var(--bv-padding-lg); /* PC 区块内边距 24px */
  --bv-section-gap: var(--bv-padding-xl); /* PC 区块间距 32px */
}

/* ---------- B. 容器形态：遮罩 ---------- */
[data-mode='pc'] {
  /* 宽屏下 0.7 的蒙层压迫感过强，PC 降到 0.45 */
  --bv-overlay-background: var(--bv-overlay-pc-background);
}

/* ---------- B. 容器形态：弹层（Popup / Dialog） ---------- */
[data-mode='pc'] {
  /* 进出场动画：H5 300ms（Vant --duration-base）→ PC 200ms 更利落 */
  --bv-popup-duration: 200ms;
  /* 形态切换：底部抽屉的 16px 大圆角 → 居中模态的 8px 常规圆角 */
  --bv-popup-round-radius: var(--bv-popup-pc-radius);
}

/* ---------- B. 容器形态：PC 端文字与按钮密度 ---------- */
[data-mode='pc'] {
  /* 居中模态的按钮沿用 48px 高（Vant 值），横向右对齐，不做压缩 */
  --bv-dialog-button-min-width: 88px;
}

/* PC 缺省值兜底：H5 下不需要该 token，但显式声明避免引用未定义变量 */
:root {
  --bv-dialog-button-min-width: 0px;
}

/**
 * Bivane · 样式原子层
 * 对应 Vant 的 mixins（hairline、active 蒙层），用纯 CSS 类实现，
 * 保证组件侧「只用 Tailwind + var(--bv-*)」的契约不被破坏。
 */

/* ---------- 细边线（对应 Vant mixins/hairline.less）---------- */
/* 原理：伪元素放大到 200% 后用 scale(0.5) 缩回，1px 边框渲染为 0.5px 物理像素 */
.bv-hairline {
  position: relative;
}

.bv-hairline::after {
  position: absolute;
  box-sizing: border-box;
  content: "";
  pointer-events: none;
  top: -50%;
  right: -50%;
  bottom: -50%;
  left: -50%;
  border: 0 solid var(--bv-hairline-color, var(--bv-border));
  transform: scale(0.5);
}

.bv-hairline--top::after {
  border-top-width: var(--bv-border-width);
}

.bv-hairline--bottom::after {
  border-bottom-width: var(--bv-border-width);
  /* 缩放后视觉内缩 = 声明值 × 2 */
  left: calc(var(--bv-hairline-inset-left, 0px) * 2);
  right: calc(var(--bv-hairline-inset-right, 0px) * 2);
}

.bv-hairline--left::after {
  border-left-width: var(--bv-border-width);
}

.bv-hairline--right::after {
  border-right-width: var(--bv-border-width);
}

.bv-hairline--all::after {
  border-width: var(--bv-border-width);
}

/* ---------- 按压态蒙层（对应 Vant 按钮的 ::before 黑色蒙层）---------- */
.bv-press {
  position: relative;
}

.bv-press::before {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 100%;
  height: 100%;
  background: var(--bv-black);
  border-radius: inherit;
  transform: translate(-50%, -50%);
  opacity: 0;
  content: "";
  pointer-events: none;
  transition: opacity var(--bv-duration-fast);
}

.bv-press:active::before {
  opacity: var(--bv-press-overlay, 0.1);
}

.bv-press:disabled::before,
.bv-press[data-disabled="true"]::before,
.bv-press[data-loading="true"]::before {
  display: none;
}

/* ---------- 滚动锁定（弹层类共用）---------- */
.bv-lock-scroll {
  overflow: hidden;
  touch-action: none;
}

/* ---------- 安全区（贴边组件共用：Popup / Dialog / Tabbar / NavBar）----------
 * 用 constant() 兜底 iOS 11.0~11.2，env() 为现代标准；
 * 顺序不可颠倒，老浏览器会忽略不认识的后者。 */
.bv-safe-area-top {
  padding-top: constant(safe-area-inset-top);
  padding-top: env(safe-area-inset-top);
}

.bv-safe-area-bottom {
  padding-bottom: constant(safe-area-inset-bottom);
  padding-bottom: env(safe-area-inset-bottom);
}

.bv-safe-area-margin-bottom {
  margin-bottom: constant(safe-area-inset-bottom);
  margin-bottom: env(safe-area-inset-bottom);
}

/* ---------- 弹层进出场动画（PC 居中模态 / 遮罩）----------
 * 为什么不写在组件里：Radix 的 Presence 靠「元素上是否有正在运行的 CSS 动画」
 * 判定退出动画何时结束、何时卸载节点，因此动画必须以 CSS 规则挂在
 * [data-state] 上，而不是走 React 的 state 分支。
 * 时长取 --bv-popup-duration，随模式变化（H5 300ms / PC 200ms）。 */
@keyframes bv-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes bv-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes bv-modal-in {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes bv-modal-out {
  from {
    opacity: 1;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(0.95);
  }
}

[data-slot="dialog-overlay"][data-state="open"] {
  animation: bv-fade-in var(--bv-popup-duration) var(--bv-ease-out);
}

[data-slot="dialog-overlay"][data-state="closed"] {
  animation: bv-fade-out var(--bv-popup-duration) var(--bv-ease-in);
}

[data-slot="dialog"][data-variant="modal"][data-state="open"] {
  animation: bv-modal-in var(--bv-popup-duration) var(--bv-ease-out);
}

[data-slot="dialog"][data-variant="modal"][data-state="closed"] {
  animation: bv-modal-out var(--bv-popup-duration) var(--bv-ease-in);
}

/* PC 的锚定下拉浮层（Select / 后续 DropdownMenu、Popover 共用）。
 * 槽名必须与 components/pc/select.tsx 上的 data-slot="select-panel" 逐字一致 ——
 * 换个名字动画会静默不跑（契约第 16 条）。
 * 时长取 --bv-select-pc-duration（120ms）：锚定浮层离触发器很近，
 * 用弹层的 200~300ms 会显得拖沓。 */
[data-slot="select-panel"][data-state="open"] {
  animation: bv-fade-in var(--bv-select-pc-duration) var(--bv-ease-out);
}

[data-slot="select-panel"][data-state="closed"] {
  animation: bv-fade-out var(--bv-select-pc-duration) var(--bv-ease-in);
}

/* PC 的 DropdownMenu 浮层与二级浮层。
 * 槽名必须与 components/pc/menu.tsx 上的 data-slot 逐字一致（契约第 16 条）。
 * SubContent 走 keyframes 而不是 transition：Radix 的子菜单是「挂载/卸载」，
 * 没有可过渡的前一帧；动画则让 Presence 能等到播完再卸载。 */
[data-slot="menu-panel"][data-state="open"] {
  animation: bv-fade-in var(--bv-menu-pc-duration) var(--bv-ease-out);
}

[data-slot="menu-panel"][data-state="closed"] {
  animation: bv-fade-out var(--bv-menu-pc-duration) var(--bv-ease-in);
}

[data-slot="menu-subpanel"][data-state="open"] {
  animation: bv-fade-in var(--bv-menu-pc-duration) var(--bv-ease-out);
}

[data-slot="menu-subpanel"][data-state="closed"] {
  animation: bv-fade-out var(--bv-menu-pc-duration) var(--bv-ease-in);
}

/* DatePicker 的 PC 月历浮层。槽名必须与 components/pc/date-picker.tsx 上的
 * data-slot="date-picker-panel" 逐字一致（契约第 16 条）。
 * 时长取 --bv-date-picker-pc-duration（160ms）：月历比单列浮层面积大，
 * 用 120ms 会显得「啪」地跳出来，用弹层的 300ms 又太慢。 */
[data-slot="date-picker-panel"][data-state="open"] {
  animation: bv-fade-in var(--bv-date-picker-pc-duration) var(--bv-ease-out);
}

[data-slot="date-picker-panel"][data-state="closed"] {
  animation: bv-fade-out var(--bv-date-picker-pc-duration) var(--bv-ease-in);
}

/* H5 滚轮列上下两端的渐隐遮罩。
 * 放在 CSS 而不是 Tailwind 类里：渐变色要用 `linear-gradient(to bottom, var(--x), transparent)`，
 * 写进 `bg-[...]` 任意值会在逗号处被 Tailwind 的解析切开。
 * 下遮罩复用同一条规则并整体 `rotate-180` —— 旋转围绕中心，底边锚定的盒子转完仍在原位。 */
[data-slot="date-picker-wheel-mask"] {
  background: linear-gradient(
    to bottom,
    var(--bv-date-picker-wheel-mask-color),
    transparent
  );
}

/* TimePicker 的 PC 浮层（可点击列表面板）。时长取 --bv-time-picker-pc-duration（160ms）。 */
[data-slot="time-picker-panel"][data-state="open"] {
  animation: bv-fade-in var(--bv-time-picker-pc-duration) var(--bv-ease-out);
}

[data-slot="time-picker-panel"][data-state="closed"] {
  animation: bv-fade-out var(--bv-time-picker-pc-duration) var(--bv-ease-in);
}

/* H5 滚轮列上下两端的渐隐遮罩（同 date-picker-wheel-mask 的来历）。 */
[data-slot="time-picker-wheel-mask"] {
  background: linear-gradient(
    to bottom,
    var(--bv-time-picker-wheel-mask-color),
    transparent
  );
}

/* DateTimePicker PC 浮层（锚定滚轮面板，时长对齐 TimePicker）。 */
[data-slot="datetime-picker-panel"][data-state="open"] {
  animation: bv-fade-in var(--bv-datetime-picker-pc-duration)
    var(--bv-ease-out);
}

[data-slot="datetime-picker-panel"][data-state="closed"] {
  animation: bv-fade-out var(--bv-datetime-picker-pc-duration)
    var(--bv-ease-in);
}

/* DateTimePicker 滚轮列渐隐遮罩（来历同 date-picker-wheel-mask）。 */
[data-slot="datetime-picker-wheel-mask"] {
  background: linear-gradient(
    to bottom,
    var(--bv-datetime-picker-wheel-mask-color),
    transparent
  );
}

/* Tooltip 跟随指针的小气泡（两端共用；只淡入淡出，位移由 JS transform 接管，
 * 不能用 bv-modal-in 的 scale —— 会与定位 transform 互相顶掉）。 */
[data-slot="tooltip-bubble"][data-state="open"] {
  animation: bv-fade-in var(--bv-tooltip-duration) var(--bv-ease-out);
}

[data-slot="tooltip-bubble"][data-state="closed"] {
  animation: bv-fade-out var(--bv-tooltip-duration) var(--bv-ease-in);
}

/* Popover 的锚定气泡（H5 轻量气泡与 PC 浮层共用同一槽名与时长；
 * H5 的底部抽屉形态走 Popup 自己的滑入动画）。 */
[data-slot="popover-panel"][data-state="open"] {
  animation: bv-fade-in var(--bv-popover-duration) var(--bv-ease-out);
}

[data-slot="popover-panel"][data-state="closed"] {
  animation: bv-fade-out var(--bv-popover-duration) var(--bv-ease-in);
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="dialog-overlay"],
  [data-slot="dialog"][data-variant="modal"],
  [data-slot="menu-panel"],
  [data-slot="menu-subpanel"],
  [data-slot="select-panel"],
  [data-slot="date-picker-panel"],
  [data-slot="time-picker-panel"],
  [data-slot="datetime-picker-panel"],
  [data-slot="tooltip-bubble"],
  [data-slot="popover-panel"] {
    animation: none;
  }
}

/**
 * Bivane · Tailwind v4 主题映射（分发文件）
 *
 * 本文件是 token 链路的第 ② 环，缺了它整套组件样式会静默失效：
 *   `--bv-*` 只是普通 CSS 变量，Tailwind 并不知道它们存在。
 *   只有在 `@theme inline` 里声明 `--color-bv-<name>`，
 *   工具类 `bg-bv-<name>` / `text-bv-<name>` 才会被生成。
 *
 * 漏掉的后果（P1 真实缺陷）：`bg-bv-overlay` 从不生成任何规则，
 * 但 `cn()` 因为 lib/utils.ts 的 BV_COLORS 已注册该命名空间，会**原样保留类名** ——
 * DOM 里查得到、toHaveClass 也过，浏览器却当普通类忽略，表现为遮罩静默全透明。
 * 更隐蔽的是产物里搜不到 `--color-bv-*`（`inline` 会把 var() 内联进声明），
 * 必须搜工具类名本身：`grep -o 'bg-bv-overlay{[^}]*}' dist/assets/*.css`
 *
 * 使用方式（消费者在 globals.css 里，顺序不可调换）：
 *   @import 'tailwindcss';
 *   @import './styles/bivane/vant.css';      // ① 变量定义
 *   @import './styles/bivane/vant-dark.css'; //    深色覆盖（可选）
 *   @import './styles/bivane/modes.css';     //    随模式变化的变量
 *   @import './styles/bivane/utilities.css'; //    安全区 / 动画原子层
 *   @import './styles/bivane/theme.css';     // ② 本文件：映射 + 变体 + 基础层
 */

/**
 * 必须使用 `inline`：工具类会把 `var(--bv-*)` 直接内联进声明，
 * 使 token 能在**任意容器级**被覆盖（深色主题 .bv-theme-dark、
 * 页面级 gutter、后续的紧凑/宽松密度模式都依赖这一点）。
 * 若不加 inline，Tailwind 会生成 `--color-bv-x: var(--bv-x)` 并在 :root 处提前求值，
 * 容器级覆盖将完全失效。
 *
 * 生成示例：bg-bv-primary / text-bv-text / border-bv-border / rounded-bv-md /
 *          text-bv-md / p-bv-md / gap-bv-gutter / py-bv-block / mb-bv-section
 */
@theme inline {
  /* 颜色 */
  --color-bv-primary: var(--bv-primary);
  --color-bv-success: var(--bv-success);
  --color-bv-danger: var(--bv-danger);
  --color-bv-warning: var(--bv-warning);
  --color-bv-text: var(--bv-text);
  --color-bv-text-2: var(--bv-text-2);
  --color-bv-text-3: var(--bv-text-3);
  --color-bv-border: var(--bv-border);
  --color-bv-background: var(--bv-background);
  --color-bv-surface: var(--bv-surface);
  --color-bv-muted: var(--bv-muted);
  --color-bv-active: var(--bv-active-color);
  --color-bv-white: var(--bv-white);
  --color-bv-black: var(--bv-black);
  --color-bv-gray-4: var(--bv-gray-4);
  --color-bv-gray-6: var(--bv-gray-6);
  /* 遮罩浓度：随模式变化（H5 .7 / PC .45），定义在 modes.css。
     漏了这行会让 bg-bv-overlay 生成不出来，而 cn() 仍保留类名 —— 表现为遮罩静默全透明。 */
  --color-bv-overlay: var(--bv-overlay-background);

  /* 圆角 */
  --radius-bv-sm: var(--bv-radius-sm);
  --radius-bv-md: var(--bv-radius-md);
  --radius-bv-lg: var(--bv-radius-lg);
  --radius-bv-max: var(--bv-radius-max);

  /* 字阶（含行高） */
  --text-bv-xs: var(--bv-font-xs);
  --text-bv-xs--line-height: var(--bv-line-xs);
  --text-bv-sm: var(--bv-font-sm);
  --text-bv-sm--line-height: var(--bv-line-sm);
  --text-bv-md: var(--bv-font-md);
  --text-bv-md--line-height: var(--bv-line-md);
  --text-bv-lg: var(--bv-font-lg);
  --text-bv-lg--line-height: var(--bv-line-lg);

  /* 间距（组件内间距，严格等于 Vant token） */
  --spacing-bv-base: var(--bv-padding-base);
  --spacing-bv-xs: var(--bv-padding-xs);
  --spacing-bv-sm: var(--bv-padding-sm);
  --spacing-bv-md: var(--bv-padding-md);
  --spacing-bv-lg: var(--bv-padding-lg);
  --spacing-bv-xl: var(--bv-padding-xl);

  /* 间距（页面级节奏，随模式变化；只用于页面骨架，不进组件内部） */
  --spacing-bv-gutter: var(--bv-gutter);
  --spacing-bv-block: var(--bv-block-padding);
  --spacing-bv-section: var(--bv-section-gap);

  /* 字重与字体 */
  --font-weight-bv-bold: var(--bv-font-bold);
  --font-bv: var(--bv-base-font);
}

/**
 * 双模式 CSS 变体（模式 A 组件书写用，见架构文档 §6.1）
 *
 * 走 data-mode 属性而非 media query —— 因为断点由 ResponsiveProvider 配置，
 * 媒体查询写死 768px 会在自定义断点下判定错误。
 * 用法：`className="bv-h5:py-bv-md bv-pc:py-bv-lg"`
 */
@custom-variant bv-h5 ([data-mode='h5'] &);
@custom-variant bv-pc ([data-mode='pc'] &);

/* 全局基础设定（对齐 Vant base.less） */
@layer base {
  html {
    font-family: var(--bv-base-font);
    -webkit-tap-highlight-color: transparent;
  }

  body {
    margin: 0;
    color: var(--bv-text);
    background: var(--bv-background);
  }

  /* PC 模式的指针约定：可点击元素统一 pointer */
  [data-slot='button']:not(:disabled),
  [data-slot='cell'][data-clickable='true'] {
    cursor: pointer;
  }
}
